add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_fee_by_payment_method' );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_fee_by_payment_method_script' );

function perfectpixel_fee_by_payment_method( $cart ) {
	if ( is_admin() && ! defined( 'DOING_AJAX' ) ) {
		return;
	}
	$chosen = WC()->session ? WC()->session->get( 'chosen_payment_method' ) : '';
	if ( '{{fee_gateway}}' !== $chosen ) {
		return;
	}
	$amount = (float) '{{fee_gateway_amount}}';
	if ( 'percent' === '{{fee_gateway_type}}' ) {
		$amount = $cart->get_subtotal() * $amount / 100;
	}
	if ( $amount > 0 ) {
		$cart->add_fee( '{{fee_gateway_label}}', $amount, true );
	}
}

// Classic checkout: recalculate totals when the payment method changes.
function perfectpixel_fee_by_payment_method_script() {
	?>
	<script>
	jQuery( function ( $ ) {
		$( 'form.checkout' ).on( 'change', 'input[name="payment_method"]', function () {
			$( document.body ).trigger( 'update_checkout' );
		} );
	} );
	</script>
	<?php
}
